/* LIQUID CHROME — restrained silver reflections, deep graphite glass */
:root{--ink:#f3f5f7;--muted:#b1b9c4;--glass:rgba(180,192,205,.075);--stroke:rgba(222,233,244,.22);--cyan:#c6d4e2;--violet:#9caabd}
body{background:#07090d;color:#f3f5f7}
.bg{background:radial-gradient(ellipse at 15% 4%,#26313d 0,transparent 38%),radial-gradient(ellipse at 88% 30%,#242a34 0,transparent 35%),radial-gradient(ellipse at 48% 100%,#151e29 0,transparent 43%),#07090d}
#liquid-metal-bg{position:fixed;inset:0;width:100%;height:100%;z-index:0;pointer-events:none;opacity:.78}
body>.nav,body>main,body>footer{position:relative;z-index:1}
.orb{opacity:.16;filter:blur(26px);mix-blend-mode:screen;background:linear-gradient(135deg,#f1f5f9,#697889,#202a36)}
.glass{background:linear-gradient(135deg,rgba(225,234,244,.115),rgba(70,83,99,.075) 45%,rgba(255,255,255,.035));border:1px solid rgba(225,235,246,.22);box-shadow:0 24px 70px #0008,inset 0 1px 0 rgba(255,255,255,.25),inset 0 -1px 0 rgba(0,0,0,.25);backdrop-filter:blur(26px) saturate(125%);-webkit-backdrop-filter:blur(26px) saturate(125%);position:relative;overflow:hidden}
.glass:before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:linear-gradient(115deg,rgba(255,255,255,.16),transparent 20%,transparent 72%,rgba(210,225,240,.08));opacity:.55}
.nav{background:rgba(20,25,32,.55);border-color:#dce7f322}
.logo{background:linear-gradient(145deg,#f7fafc 0%,#a9b5c2 22%,#414d5a 47%,#e5edf4 66%,#6d7b8b 100%);color:#111820;box-shadow:0 5px 25px #c5d5e622,inset 0 1px #fff}
.btn{background:linear-gradient(115deg,#f4f7fa 0%,#aebac7 18%,#eef3f7 32%,#6b7887 54%,#dbe4ec 73%,#8d9baa 100%);background-size:220% 100%;color:#10151c;border:1px solid #f4f7fa88;box-shadow:0 8px 30px #c3d1df20,inset 0 1px #fff9;transition:transform .25s,box-shadow .25s,background-position .45s}
.btn:hover{background-position:100% 0;box-shadow:0 14px 34px #c3d1df30,inset 0 1px #fff;transform:translateY(-3px)}
.btn.secondary{background:linear-gradient(130deg,#ffffff13,#5f6b7a18);color:#edf2f7;border-color:#dfe8f333;box-shadow:inset 0 1px #ffffff16}
.pill{border-color:#d7e1eb50;background:#c7d4e20b;color:#e0e7ee}.pulse{background:#dce9f3;box-shadow:0 0 0 5px #dce9f318}
.gradient{background:linear-gradient(100deg,#fff 0%,#c4ced8 25%,#fff 43%,#7e8b9b 60%,#edf3f8 78%,#a9b6c5 100%);background-size:220% 100%;animation:chromeSweep 9s ease-in-out infinite alternate;-webkit-background-clip:text;background-clip:text;color:transparent}
@keyframes chromeSweep{to{background-position:100% 0}}
.ring{border-color:#dfe8f426;box-shadow:0 0 90px #cbd8e50b,inset 0 0 60px #dbe7f008}.ring:before{background:#e5edf4;box-shadow:0 0 22px #dce6ef}.ring:after{background:#8998a8;box-shadow:0 0 24px #b7c5d5}
.metric,.mini-row{background:linear-gradient(125deg,#e9f0f70e,#6d7c8c0a);border-color:#e2ebf21b}.mini-icon{background:linear-gradient(145deg,#edf3fa24,#68798c30);color:#e4ebf2;border:1px solid #dce6f025}
.feature:hover{border-color:#dce8f36b}.section-head .eyebrow,.num{color:#d2dce6}.float-card{background:linear-gradient(135deg,#c9d5e218,#ffffff08);border:1px solid #dce8f32b;box-shadow:0 15px 45px #0004,inset 0 1px #ffffff20;backdrop-filter:blur(24px)}
#liquid-metal-bg~.nav{isolation:isolate}
@media(prefers-reduced-motion:reduce){.gradient{animation:none}}

/* PEARL LIQUID GLASS — bright, calm, premium product aesthetic */
:root{--ink:#252a32;--muted:#6f7782;--glass:rgba(255,255,255,.60);--stroke:rgba(255,255,255,.88);--cyan:#8d96a4;--violet:#c5b7e8}
html{background:#f4f4f2}body{color:#252a32;background:#f4f4f2;isolation:isolate}
