.brand{color:#252a32}.logo{background:linear-gradient(145deg,#fff 0%,#e5e8ec 24%,#aab3bd 48%,#fff 67%,#c0c8d1 100%);color:#343b45;box-shadow:0 8px 22px #6f7b8a20,inset 0 1px #fff;border:1px solid #fff}
.brand small{color:#7d8590}.navlinks{color:#606873}.navlinks a:hover{color:#252a32}
.btn{background:linear-gradient(115deg,#fff 0%,#dfe3e7 20%,#fdfdfd 37%,#b5bec8 57%,#f8fafb 76%,#c4ccd4 100%);background-size:220% 100%;color:#2d333b;border:1px solid #fff;box-shadow:0 9px 25px rgba(80,91,105,.16),inset 0 1px #fff;transition:transform .25s,box-shadow .25s,background-position .4s}
.btn:hover{background-position:100% 0;box-shadow:0 14px 30px rgba(80,91,105,.2),inset 0 1px #fff;transform:translateY(-2px)}.btn.secondary{background:rgba(255,255,255,.54);color:#4c535d;border-color:rgba(255,255,255,.95);box-shadow:0 6px 20px #68717d10,inset 0 1px #fff}
.pill{border-color:#d8dce1;background:rgba(255,255,255,.68);color:#626b77}.pulse{background:#8cbaa5;box-shadow:0 0 0 5px #8cbaa51a}.hero h1{color:#252a32}.gradient{background:linear-gradient(100deg,#3e4650 0%,#a1a9b3 34%,#6f7782 57%,#b7a8d7 84%,#6c7480);background-size:200% auto;animation:pearlShine 9s ease-in-out infinite alternate;-webkit-background-clip:text;background-clip:text;color:transparent}
.hero p,.section-head p,.step p,.feature p,.cta p{color:#727983}.micro{color:#707883}.avatars span{border-color:#f3f3f0;background:linear-gradient(145deg,#fff,#c8ced5 45%,#e9e4f1);color:#444b55}.device-top{color:#5c6470}.live{color:#6d9d87}.screen-title{color:#303741}.muted{color:#7b838d}.metric{background:rgba(255,255,255,.58);border-color:#fff;box-shadow:0 7px 18px #5b657010,inset 0 1px #fff}.metric .label,.metric .label{color:#7a828c}.metric .n{color:#343b44}.mini-row{background:rgba(255,255,255,.58);border:1px solid #fff;box-shadow:0 7px 20px #5b65700b}.mini-icon{background:linear-gradient(145deg,#fff,#dfe3e8 55%,#e7e1f0);color:#65707c;border:1px solid #fff}.mini-row small{color:#838a93}.ring{border-color:#fff9;box-shadow:0 0 70px #b9c0c81f,inset 0 0 55px #fff7}.ring:before{background:#fff;box-shadow:0 0 18px #fff}.ring:after{background:#c5b9df;box-shadow:0 0 20px #c5b9df}.float-card{background:rgba(255,255,255,.74);border-color:#fff;box-shadow:0 14px 35px #5b65701b,inset 0 1px #fff;color:#363d46}.float-card span{color:#7a828c!important}
.section-head .eyebrow,.num{color:#7d8792}.section-head h2,.feature h3,.step h3,.cta h2{color:#30363f}.feature,.step{background:linear-gradient(135deg,rgba(255,255,255,.73),rgba(255,255,255,.4));border-color:#fff;box-shadow:0 16px 40px #68717d0c,inset 0 1px #fff}.feature:hover{border-color:#c6cbd2;box-shadow:0 20px 44px #68717d18}.feature-icon{background:linear-gradient(145deg,#fff,#e1e4e8 55%,#e7e0f0);border-color:#fff;color:#6b7480}.cta{background:linear-gradient(125deg,rgba(255,255,255,.85),rgba(226,229,232,.62));border:1px solid #fff;box-shadow:0 20px 55px #68717d14,inset 0 1px #fff}.footer{border-top-color:#dfe2e4;color:#858b93}
