<script>const items=document.querySelectorAll('.reveal');if('IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.12});items.forEach(el=>io.observe(el))}else{items.forEach(el=>el.classList.add('visible'))}</script><script>
(() => {
 const canvas=document.getElementById('liquid-metal-bg'); if(!canvas)return;
 const ctx=canvas.getContext('2d',{alpha:true}); if(!ctx)return;
 const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 let w=0,h=0,dpr=1,tx=-9999,ty=-9999,mx=-9999,my=-9999,frame=0;
 const blobs=[{x:.18,y:.22,r:.25,vx:.00012,vy:.00017,phase:.3},{x:.76,y:.2,r:.21,vx:-.00014,vy:.00011,phase:2.2},{x:.53,y:.75,r:.3,vx:.0001,vy:-.00012,phase:4.4},{x:.92,y:.82,r:.19,vx:-.0001,vy:-.00015,phase:1.3}];
 function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,1.6);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}
 function pointer(e){tx=e.clientX;ty=e.clientY} window.addEventListener('pointermove',pointer,{passive:true});window.addEventListener('pointerleave',()=>{tx=-9999;ty=-9999},{passive:true});window.addEventListener('resize',resize,{passive:true});resize();
 function draw(t){frame++;mx+=(tx-mx)*.055;my+=(ty-my)*.055;ctx.clearRect(0,0,w,h);
  const time=reduce?0:t*.00008;ctx.globalCompositeOperation='screen';
  blobs.forEach((b,i)=>{let x=(b.x+Math.sin(time+b.phase)*.035)*w,y=(b.y+Math.cos(time*1.15+b.phase)*.045)*h; if(mx>-1000){const dx=(mx-x)/Math.max(w,1),dy=(my-y)/Math.max(h,1),pull=Math.max(0,1-Math.hypot(dx,dy)*1.6);x+=dx*w*pull*.105;y+=dy*h*pull*.105}
   const r=b.r*Math.min(w,h),g=ctx.createRadialGradient(x-r*.18,y-r*.25,r*.02,x,y,r);g.addColorStop(0,'rgba(245,250,255,.19)');g.addColorStop(.17,'rgba(180,198,216,.115)');g.addColorStop(.36,'rgba(107,126,147,.075)');g.addColorStop(.58,'rgba(48,62,79,.035)');g.addColorStop(1,'rgba(12,17,25,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();
   // narrow specular crescent gives the fluid a brushed liquid-chrome edge
   ctx.beginPath();ctx.ellipse(x-r*.08,y-r*.05,r*.7,r*.39,(t*.00006+b.phase)*.6,Math.PI*1.05,Math.PI*1.8);ctx.strokeStyle='rgba(226,237,248,'+(.07+Math.sin(t*.0004+b.phase)*.025)+')';ctx.lineWidth=Math.max(1,r*.006);ctx.stroke();
  });
  if(mx>-1000){const r=Math.min(w,h)*.22,g=ctx.createRadialGradient(mx,my,0,mx,my,r);g.addColorStop(0,'rgba(210,226,242,.065)');g.addColorStop(.42,'rgba(160,181,204,.025)');g.addColorStop(1,'rgba(150,175,200,0)');ctx.fillStyle=g;ctx.fillRect(mx-r,my-r,r*2,r*2)}
  ctx.globalCompositeOperation='source-over';if(!reduce)requestAnimationFrame(draw)
 }
 if(reduce)draw(0);else requestAnimationFrame(draw);
})();
</script></body></html>